#include <stdio.h>
#include <stdlib.h>

/* Provided by the candidate in solution.c */
int remove_duplicates(int *values, int count);

static int read_int_array(int **out, int *count_out)
{
    int count;
    if (scanf("%d", &count) != 1 || count < 0) {
        return 0;
    }
    int *values = NULL;
    if (count > 0) {
        values = malloc((size_t)count * sizeof *values);
        if (values == NULL) {
            return 0;
        }
        for (int i = 0; i < count; i++) {
            if (scanf("%d", &values[i]) != 1) {
                free(values);
                return 0;
            }
        }
    }
    *out = values;
    *count_out = count;
    return 1;
}

int main(void)
{
    int *values = NULL;
    int count = 0;
    if (!read_int_array(&values, &count)) {
        return 1;
    }

    int unique = remove_duplicates(values, count);
    printf("%d\n", unique);
    for (int i = 0; i < unique; i++) {
        printf("%d%s", values[i], (i + 1 < unique) ? " " : "");
    }
    printf("\n");

    free(values);
    return 0;
}
